import sys
sys.setrecursionlimit(10000)
MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    pts = [None] * n
    for j in range(n):
        x, y = data[1 + 2*j:3 + 2*j]
        pts[x-1] = y-1
    # Incomparable pairs in the dominance order.
    inc = [0] * n
    for i in range(n):
        for j in range(i):
            if (i-j) * (pts[i]-pts[j]) < 0:
                inc[i] |= 1 << j
                inc[j] |= 1 << i
    # Enumerate antichains and collect their common incomparability sets.
    # An antichain is exactly a possible set of operation centers.
    answers = set()
    def dfs(pos, chosen, common):
        if pos == n:
            answers.add(common)
            return
        dfs(pos+1, chosen, common)
        if (chosen & ~inc[pos]) == 0:
            dfs(pos+1, chosen | (1 << pos), common & inc[pos])
    dfs(0, 0, (1 << n)-1)
    print(len(answers) % MOD)

if __name__ == '__main__':
    main()

