import sys
MOD=998244353

def factor(x):
    result = []
    d = 2
    while d * d <= x:
        if x % d == 0:
            e = 0
            while x % d == 0:
                x //= d
                e += 1
            result.append((d, e))
        d += 1
    if x > 1:
        result.append((x, 1))
    return result

data = list(map(int, sys.stdin.buffer.read().split()))
n = data[0]
fac = [factor(x) for x in data[1:]]
primes = {p for fs in fac for p, e in fs}
answer = 1
for p in primes:
    exponents = [dict(fs).get(p, 0) for fs in fac]
    dp = {0: 1}
    t = 1  # number of positions already processed
    for e in exponents:
        next_dp = {}
        steps = (e, -e) if e else (0,)
        for height, ways in dp.items():
            for delta in steps:
                new_height = height + delta
                if new_height >= 0:
                    centered = new_height
                    area_increase = centered
                else:
                    # The new position sets a lower minimum. All previous
                    # centered heights increase by -new_height.
                    centered = 0
                    area_increase = (-new_height) * t
                value = ways * pow(p, area_increase, MOD) % MOD
                next_dp[centered] = (next_dp.get(centered, 0) + value) % MOD
        dp = next_dp
        t += 1
    answer = answer * (sum(dp.values()) % MOD) % MOD
print(answer)

