import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    values = data[1:1 + n]
    limit = max(values)

    spf = list(range(limit + 1))
    for p in range(2, int(limit ** 0.5) + 1):
        if spf[p] == p:
            for x in range(p * p, limit + 1, p):
                if spf[x] == x:
                    spf[x] = p

    nim_sum = 0
    for value in values:
        count = 0
        while value > 1:
            value //= spf[value]
            count += 1
        nim_sum ^= count

    print('Anna' if nim_sum else 'Bruno')

if __name__ == '__main__':
    main()

