from typing import List
import heapq

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        buckets = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            x, y = (a, b) if a < b else (b, a)
            buckets[y].append((x, i))

        freq = [0] * (n + 1)
        active_ids = [[] for _ in range(n + 1)]
        heap = []
        total = 0
        gains = [0] * len(conflictingPairs)

        for r in range(1, n + 1):
            for x, idx in buckets[r]:
                if freq[x] == 0:
                    heapq.heappush(heap, -x)
                freq[x] += 1
                active_ids[x].append(idx)

            if heap:
                top = -heap[0]
                total += r - top
                if freq[top] == 1:
                    heapq.heappop(heap)
                    second = -heap[0] if heap else 0
                    heapq.heappush(heap, -top)
                    gains[active_ids[top][0]] += top - second
            else:
                total += r

        return total + max(gains)

