import sys

def main():
    input = sys.stdin.buffer.readline
    N, M, Q = map(int, input().split())
    edges = [None] * M
    for i in range(M):
        a, b, c = map(int, input().split())
        edges[i] = (a-1, b-1, c)
    queries = []
    closed = [False] * M
    for _ in range(Q):
        t, *v = map(int, input().split())
        if t == 1:
            e = v[0]-1
            closed[e] = True
            queries.append((1, e))
        else:
            queries.append((2, v[0]-1, v[1]-1))

    INF = 10**30
    d = [[INF] * N for _ in range(N)]
    for i in range(N):
        d[i][i] = 0
    for i, (a, b, c) in enumerate(edges):
        if not closed[i]:
            d[a][b] = d[b][a] = c

    for k in range(N):
        dk = d[k]
        for i in range(N):
            dik = d[i][k]
            if dik == INF:
                continue
            di = d[i]
            for j in range(N):
                nd = dik + dk[j]
                if nd < di[j]:
                    di[j] = nd

    ans = []
    for q in reversed(queries):
        if q[0] == 2:
            val = d[q[1]][q[2]]
            ans.append(str(val if val < INF else -1))
        else:
            a, b, c = edges[q[1]]
            au = [d[i][a] for i in range(N)]
            bu = [d[i][b] for i in range(N)]
            for i in range(N):
                di = d[i]
                for j in range(i, N):
                    x = au[i] + c + bu[j]
                    y = bu[i] + c + au[j]
                    if x < di[j]:
                        di[j] = x
                        d[j][i] = x
                    if y < di[j]:
                        di[j] = y
                        d[j][i] = y
    sys.stdout.write('\n'.join(reversed(ans)))

if __name__ == '__main__':
    main()

