            comb[a][0] = comb[a][a] = 1
            for b in range(1, a):
                comb[a][b] = (comb[a - 1][b - 1] + comb[a - 1][b]) % MOD

        ans = 0
        for target in range(1, nbits + 1):
            if steps[target] > k - 1:
                continue
            ones = 0
            ways = 0
            for i, ch in enumerate(s):
                if ch == '1':
                    remaining = nbits - i - 1
                    need = target - ones
                    if 0 <= need <= remaining:
                        ways += comb[remaining][need]
                    ones += 1
            ans = (ans + ways) % MOD
        return ans

