def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data: return
    n,m=data[:2]
    rows=[0]*n; p=2
    for _ in range(m):
        u,v=data[p]-1,data[p+1]-1; p+=2
        rows[u] |= 1<<v; rows[v] |= 1<<u
    r=0; pivots=[]
    for c in range(n):
        q=next((i for i in range(r,n) if (rows[i]>>c)&1),None)
        if q is None: continue
        rows[r],rows[q]=rows[q],rows[r]
        for i in range(n):
            if i!=r and ((rows[i]>>c)&1): rows[i]^=rows[r]
        pivots.append(c); r+=1
    ps=set(pivots); free=[c for c in range(n) if c not in ps]
    if not free:
        print('No'); return
    offset=2 if len(free)<=58 and m>0 else 0
    values=[0]*n
    for j,f in enumerate(free):
        vec=1<<f
        for i,c in enumerate(pivots):
            if (rows[i]>>f)&1: vec |= 1<<c
        for v in range(n):
            if (vec>>v)&1: values[v] |= 1<<(j+offset)
    if any(x==0 for x in values): print('No')
    else:
        print('Yes'); print(*values)
