from typing import List
from array import array

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        size = n * m
        dirs = ((1, 1), (1, -1), (-1, -1), (-1, 1))
        # State 0 expects 2; state 1 expects 0.
        straight = [[array('H', [0]) * size for _ in range(2)] for _ in range(4)]

        for d, (dr, dc) in enumerate(dirs):
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            for r in rows:
                for c in cols:
                    i = r * m + c
                    nr, nc = r + dr, c + dc
                    inside = 0 <= nr < n and 0 <= nc < m
                    for state, value in enumerate((2, 0)):
                        if grid[r][c] == value:
                            straight[d][state][i] = 1 + (
                                straight[d][1 - state][nr * m + nc] if inside else 0
                            )

        answer = 1
        for d, (dr, dc) in enumerate(dirs):
            turned = [array('H', [0]) * size for _ in range(2)]
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            td = (d + 1) % 4
            tr, tc = dirs[td]
            for r in rows:
                for c in cols:
                    i = r * m + c
                    nr, nc = r + dr, c + dc
                    inside = 0 <= nr < n and 0 <= nc < m
                    for state, value in enumerate((2, 0)):
                        if grid[r][c] != value:
                            continue
                        best = 0
                        if inside:
                            j = nr * m + nc
                            best = turned[1 - state][j]
                            ar, ac = r + tr, c + tc
                            if 0 <= ar < n and 0 <= ac < m:
                                best = max(best, straight[td][1 - state][ar * m + ac])
                        turned[state][i] = 1 + best

            for r in range(n):
                for c in range(m):
                    if grid[r][c] == 1:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m:
                            answer = max(answer, 1 + turned[0][nr * m + nc])
        return answer

