class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        weights = []
        for i in range(m):
            j = n - 1 - i
            w = pow(10, i, k)
            if i != j:
                w = (w + pow(10, j, k)) % k
            weights.append(w)

        # suffix[i] is a bitmask of all residues achievable by positions i..m-1.
        suffix = [0] * (m + 1)
        suffix[m] = 1  # residue zero
        for i in range(m - 1, -1, -1):
            mask = 0
            lo = 1 if i == 0 else 0
            nxt = suffix[i + 1]
            for r in range(k):
                if nxt >> r & 1:
                    for d in range(lo, 10):
                        mask |= 1 << ((r + d * weights[i]) % k)
            suffix[i] = mask

        digits = []
        rem = 0
        for i, w in enumerate(weights):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                need = (-rem - d * w) % k
                if suffix[i + 1] >> need & 1:
                    digits.append(str(d))
                    rem = (rem + d * w) % k
                    break

        left = ''.join(digits)
        return left + (left[:-1][::-1] if n % 2 else left[::-1])

