class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n=len(nums); nxt=[n]*n; st=[]
        for i in range(n-1,-1,-1):
            while st and nums[st[-1]] <= nums[i]: st.pop()
            nxt[i]=st[-1] if st else n; st.append(i)
        pref=[0]*(n+1)
        for i,x in enumerate(nums): pref[i+1]=pref[i]+x
        LOG=n.bit_length(); go=[nxt]
        cost=[[nums[i]*(nxt[i]-i)-(pref[nxt[i]]-pref[i]) for i in range(n)]]
        for j in range(1,LOG):
            pg,pc=go[-1],cost[-1]; ng=[n]*n; nc=[0]*n
            for i in range(n):
                mid=pg[i]
                if mid<n: ng[i]=pg[mid]; nc[i]=pc[i]+pc[mid]
            go.append(ng); cost.append(nc)
        def get(l,r):
            total=0; p=l
            for j in range(LOG-1,-1,-1):
                if p==n: break
                q=go[j][p]
                if q<=r+1:
                    total+=cost[j][p]; p=q
            if p<=r: total+=nums[p]*(r-p+1)-(pref[r+1]-pref[p])
            return total
        ans=0
        for r in range(n):
            lo,hi=0,r+1
            while lo<hi:
                mid=(lo+hi)//2
                if get(mid,r)<=k: hi=mid
                else: lo=mid+1
            ans+=r-lo+1
        return ans

