class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter
        c = [Counter(s).get(chr(97+i), 0) for i in range(26)]
        n = len(s)
        ans = n
        for k in range(1, max(c)+1):
            # dp[x]: min cost through previous letter, with x units carried here
            dp = [0] + [10**9]*n
            for cnt in c:
                # For each outgoing z, minimize dp[x] + |cnt+x-z-y| over y in {0,k}
                # absolute distance transform of dp, queried at z+y-cnt
                left = [0]*(n+1)
                left[0] = dp[0]
                for x in range(1,n+1):
                    left[x] = min(dp[x], left[x-1]+1)
                right = [0]*(n+1)
                right[n] = dp[n]
                for x in range(n-1,-1,-1):
                    right[x] = min(dp[x], right[x+1]+1)
                ndp = [10**9]*(n+1)
                for z in range(n+1):
                    best = 10**9
                    for y in (0,k):
                        t = z+y-cnt
                        if t < 0:
                            val = left[0] - t
                        elif t > n:
                            val = right[n] + (t-n)
                        else:
                            val = min(left[t], right[t])
                        best = min(best,val)
                    ndp[z] = z+best
                dp = ndp
            ans = min(ans, dp[0])
        return ans

