from typing import List

class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        parent = [-1] * n
        parent[0] = 0
        order = [0]
        for u in order:
            for v, _ in graph[u]:
                if v == parent[u]:
                    continue
                parent[v] = u
                order.append(v)

        dp0 = [0] * n  # best subtree value if the parent edge is removed
        dp1 = [0] * n  # best subtree value if the parent edge is retained
        for u in reversed(order):
            base = 0
            gains = []
            for v, w in graph[u]:
                if parent[v] == u:
                    base += dp0[v]
                    gains.append(w + dp1[v] - dp0[v])

            gains.sort(reverse=True)
            total = 0
            for gain in gains[:k]:
                if gain <= 0:
                    break
                total += gain
            dp0[u] = base + total

            total = 0
            for gain in gains[:max(0, k - 1)]:
                if gain <= 0:
                    break
                total += gain
            dp1[u] = base + total

        return dp0[0]

