import sys
from functools import lru_cache

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m, l = data[:3]
    vals = data[3:]
    A = vals[:n]
    B = vals[n:n + m]
    C = vals[n + m:]
    cards = A + B + C
    k = len(cards)
    full = (1 << k) - 1

    @lru_cache(None)
    def win(a, b, turn):
        hand = a if turn == 0 else b
        if not hand:
            return False
        table = full ^ (a | b)
        while hand:
            bit = hand & -hand
            hand -= bit
            x = bit.bit_length() - 1

            # Play the card and take nothing.
            if turn == 0:
                if not win(a ^ bit, b, 1):
                    return True
            else:
                if not win(a, b ^ bit, 0):
                    return True

            # Or take a lower-valued card from the table.
            available = table | bit
            while available:
                ybit = available & -available
                available -= ybit
                y = ybit.bit_length() - 1
                if cards[y] < cards[x]:
                    if turn == 0:
                        if not win((a ^ bit) | ybit, b, 1):
                            return True
                    else:
                        if not win(a, (b ^ bit) | ybit, 0):
                            return True
        return False

    initial_a = (1 << n) - 1
    initial_b = ((1 << m) - 1) << n
    print("Takahashi" if win(initial_a, initial_b, 0) else "Aoki")

if __name__ == "__main__":
    main()

