import sys

class BIT:
    def __init__(self, n):
        self.n = n
        self.c = [0] * (n + 1)
        self.s = [0] * (n + 1)
    def add(self, i, dc, ds):
        i += 1
        while i <= self.n:
            self.c[i] += dc
            self.s[i] += ds
            i += i & -i
    def pref(self, k):
        c = s = 0
        while k:
            c += self.c[k]
            s += self.s[k]
            k -= k & -k
        return c, s
    def smallest(self, k):
        if k == 0: return 0
        idx = 0
        bit = 1 << (self.n.bit_length() - 1)
        while bit:
            nxt = idx + bit
            if nxt <= self.n and self.c[nxt] < k:
                idx = nxt
                k -= self.c[nxt]
            bit >>= 1
        # idx is number of coordinates fully skipped; value at idx+1 supplies remainder
        c, s = self.pref(idx)
        return s + (k * vals[idx])

def main():
