    b = BIT(len(vals))
    for x in a: b.add(pos[x], 1, x)
    def score(length):
        m = length // 2
        total = b.pref(len(vals))[1]
        return total - 2 * b.smallest(m)
    ans = -1
    # survivor i must be even; progressively shift items from suffix to prefix
    pre = BIT(len(vals))
    # initially prefix empty, suffix all
    for i, x in enumerate(a):
        b.add(pos[x], -1, -x)
        if i % 2 == 0:
            ans = max(ans, score(i) + (lambda: 0)())
            # suffix score with current b, but need prefix score separately
            # handled below
        pre.add(pos[x], 1, x)
    # redo with proper two structures
    suf = BIT(len(vals))
    for x in a: suf.add(pos[x],1,x)
    pre = BIT(len(vals))
    ans = 0
    for i,x in enumerate(a):
        suf.add(pos[x],-1,-x)
        if i % 2 == 0:
            def sc(bit, length):
                m=length//2
                return bit.pref(len(vals))[1]-2*bit.smallest(m)
            ans=max(ans,sc(pre,i)+sc(suf,n-i-1))
        pre.add(pos[x],1,x)
