from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(word):
            if not word:
                return list(range(n + 1))
            m = len(word)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and word[i] != word[j]:
                    j = pi[j - 1]
                if word[i] == word[j]:
                    j += 1
                pi[i] = j
            out = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != word[j]:
                    j = pi[j - 1]
                if ch == word[j]:
                    j += 1
                if j == m:
                    out.append(i - m + 1)
                    j = pi[j - 1]
            return out

        apos, bpos, cpos = occurrences(a), occurrences(b), occurrences(c)
        ans = n + 1
        for start in apos:
            bi = bisect_left(bpos, start + len(a))
            if bi == len(bpos):
                continue
            bs = bpos[bi]
            ci = bisect_left(cpos, bs + len(b))
            if ci == len(cpos):
                continue
            end = cpos[ci] + len(c)
            ans = min(ans, end - start)
        return -1 if ans == n + 1 else ans

