    for _ in range(m):
        x,y,z=data[k]-1,data[k+1]-1,data[k+2]
        k+=3
        g[x].append((y,z))
        g[y].append((x,z))

    p=[-1]*n
    ans=[0]*n
    for s in range(n):
        if p[s]!=-1:
            continue
        p[s]=0
        stack=[s]
        nodes=[]
        while stack:
            u=stack.pop()
            nodes.append(u)
            for v,z in g[u]:
                val=p[u]^z
                if p[v]==-1:
                    p[v]=val
                    stack.append(v)
                elif p[v]!=val:
                    print(-1)
                    return

        counts=[0]*31
        for u in nodes:
            value=p[u]
            for bit in range(31):
                counts[bit]+=(value>>bit)&1
        offset=0
        size=len(nodes)
        for bit in range(31):
            if counts[bit]>size-counts[bit]:
                offset|=1<<bit
        for u in nodes:
            ans[u]=p[u]^offset

    print(*ans)

