import sys

def main():
    data = sys.stdin.buffer.read().split()
    k = int(data[0])
    a, b = data[1], data[2]
    n, m = len(a), len(b)

    if abs(n - m) > k:
        print("No")
        return

    # On diagonal d = j - i, keep the greatest i reachable using
    # exactly e edits, then extend through the matching substring.
    def extend(i, d):
        j = i + d
        if i < 0 or j < 0 or i > n or j > m:
            return -1
        limit = min(n - i, m - j)
        lo, hi = 0, limit
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if a[i:i + mid] == b[j:j + mid]:
                lo = mid
            else:
                hi = mid - 1
        return i + lo

    cur = {0: extend(0, 0)}
    if cur[0] == n and n == m:
        print("Yes")
        return

    for _ in range(k):
        nxt = {}
        for d, i in cur.items():
            # Delete from a, insert into a, or substitute one character.
            for nd, ni in ((d - 1, i + 1), (d + 1, i), (d, i + 1)):
                nj = ni + nd
                if ni > n or nj > m or ni < 0 or nj < 0:
                    continue
                if ni > nxt.get(nd, -1):
                    nxt[nd] = extend(ni, nd)
        cur = nxt
        if any(i == n and i + d == m for d, i in cur.items()):
            print("Yes")
            return
        if not cur:
            break

    print("No")

