from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        post = []
        stack = [(0, False)]
        while stack:
            v, done = stack.pop()
            if done:
                post.append(v)
            else:
                stack.append((v, True))
                for u in reversed(children[v]):
                    stack.append((u, False))

        size = [1] * n
        for v in post:
            if parent[v] != -1:
                size[parent[v]] += size[v]

        pos = [0] * n
        chars = []
        for i, v in enumerate(post):
            pos[v] = i
            chars.append(s[v])

        odd = [0] * n
        l, r = 0, -1
        for i in range(n):
            k = 1 if i > r else min(odd[l + r - i], r - i + 1)
            while i - k >= 0 and i + k < n and chars[i-k] == chars[i+k]:
                k += 1
            odd[i] = k
            if i + k - 1 > r:
                l, r = i-k+1, i+k-1

        even = [0] * n
        l, r = 0, -1
        for i in range(n):
            k = 0 if i > r else min(even[l + r - i + 1], r - i + 1)
            while i-k-1 >= 0 and i+k < n and chars[i-k-1] == chars[i+k]:
                k += 1
            even[i] = k
            if i + k - 1 > r:
                l, r = i-k, i+k-1

        ans = [False] * n
        for v in range(n):
            end = pos[v]
            start = end - size[v] + 1
            length = size[v]
            if length & 1:
                ans[v] = odd[(start + end) // 2] >= length // 2 + 1
            else:
                ans[v] = even[(start + end + 1) // 2] >= length // 2
        return ans

