from math import gcd

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        ans = 0
        for removed in range(-1, len(nums)):
            g = 0
            l = 1
            count = 0
            for i, x in enumerate(nums):
                if i == removed:
                    continue
                count += 1
                g = gcd(g, x)
                l = l // gcd(l, x) * x
            if count:
                ans = max(ans, g * l)
        return ans

