def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    it=iter(data)
    n=next(it)
    mg=next(it)
    G=[[False]*n for _ in range(n)]
    for _ in range(mg):
        u=next(it)-1; v=next(it)-1
        G[u][v]=G[v][u]=True
    mh=next(it)
    H=[[False]*n for _ in range(n)]
    for _ in range(mh):
        u=next(it)-1; v=next(it)-1
        H[u][v]=H[v][u]=True
    A=[[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(i+1,n):
            x=next(it)
            A[i][j]=A[j][i]=x
    ans=10**30
    for p in permutations(range(n)):
        cost=0
        for i in range(n):
            for j in range(i+1,n):
                if G[i][j] != H[p[i]][p[j]]:
                    cost += A[p[i]][p[j]]
        if cost<ans: ans=cost
    print(ans)

if __name__ == '__main__': main()

