class Solution:
    def countPairs(self, nums: List[int]) -> int:
        width = max(len(str(x)) for x in nums)
        arr = [str(x).zfill(width) for x in nums]
        ans = 0
        for i in range(len(arr)):
            a = arr[i]
            for j in range(i + 1, len(arr)):
                b = arr[j]
                diff = [k for k in range(width) if a[k] != b[k]]
                if not diff:
                    ans += 1
                elif len(diff) == 2:
                    p, q = diff
                    if a[p] == b[q] and a[q] == b[p]:
                        ans += 1
        return ans

