from typing import List

class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return 0

        # Li Chao tree over integer query coordinates [0, n-1].
        lines = [None] * (4 * n)

        def add_line(m, b, node=1, left=0, right=n-1):
            cur = lines[node]
            if cur is None:
                lines[node] = (m, b)
                return
            mid = (left + right) // 2
            cm, cb = cur
            if m * mid + b > cm * mid + cb:
                lines[node], (m, b) = (m, b), cur
                cm, cb = lines[node]
            if left == right:
                return
            if m * left + b > cm * left + cb:
                add_line(m, b, node * 2, left, mid)
            elif m * right + b > cm * right + cb:
                add_line(m, b, node * 2 + 1, mid + 1, right)

        def query(x, node=1, left=0, right=n-1):
            line = lines[node]
            best = line[0] * x + line[1] if line is not None else None
            if left == right:
                return best
            mid = (left + right) // 2
            if x <= mid:
                other = query(x, node * 2, left, mid)
            else:
                other = query(x, node * 2 + 1, mid + 1, right)
            return other if best is None or (other is not None and other > best) else best

        add_line(nums[0], 0)
        dp = 0
        for j in range(1, n):
            dp = query(j)
            if j < n - 1:
                add_line(nums[j], dp - j * nums[j])
        return dp

