class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return 0

        # Li Chao tree over integer query coordinates [0, n-1].
        lines = [None] * (4 * n)

        def add_line(m, b, node=1, left=0, right=n-1):
            cur = lines[node]
            if cur is None:
                lines[node] = (m, b)
                return
            mid = (left + right) // 2
            cm, cb = cur
            # Keep the better line at midpoint, send the other to the side
