import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        sieve = bytearray(b'\x01') * 10000
        sieve[0:2] = b'\x00\x00'
        for p in range(2, 100):
            if sieve[p]:
                start = p * p
                sieve[start:10000:p] = b'\x00' * (((9999 - start) // p) + 1)

        if sieve[n] or sieve[m]:
            return -1

        lo = 10 ** (len(str(n)) - 1)
        hi = lo * 10 - 1
        dist = {n: n}
        pq = [(n, n)]

        while pq:
            cost, x = heapq.heappop(pq)
            if dist.get(x) != cost:
                continue
            if x == m:
                return cost

            place = 1
            while place <= hi:
                digit = (x // place) % 10
                if digit < 9:
                    y = x + place
                    if y <= hi and not sieve[y]:
                        new_cost = cost + y
                        if new_cost < dist.get(y, 10**30):
                            dist[y] = new_cost
                            heapq.heappush(pq, (new_cost, y))
                if digit > 0:
                    y = x - place
                    if y >= lo and not sieve[y]:
                        new_cost = cost + y
                        if new_cost < dist.get(y, 10**30):
                            dist[y] = new_cost
                            heapq.heappush(pq, (new_cost, y))
                place *= 10

        return -1

