from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # z[i] is the LCP length of nums and nums[i:].
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        answer = 0
        for i in range(1, n - 1):
            # nums[:i] is a prefix of nums[i:j] for every j iff this holds.
            if z[i] >= i:
                answer += n - i - 1
                continue

            # Otherwise count splits where the second part is a prefix of the third.
            # If its length is k, both it and the matching prefix must fit.
            limit = (n - i) // 2
            if limit == 0:
                continue

            m = n - i
            # Z-array of the suffix nums[i:]. At offset k, it gives LCP(i, i+k).
            suffix_z = [0] * m
            l = r = 0
            for p in range(1, m):
                if p < r:
                    suffix_z[p] = min(r - p, suffix_z[p - l])
                while p + suffix_z[p] < m and nums[i + suffix_z[p]] == nums[i + p + suffix_z[p]]:
                    suffix_z[p] += 1
                if p + suffix_z[p] > r:
                    l, r = p, p + suffix_z[p]

            for k in range(1, limit + 1):
                if suffix_z[k] >= k:
                    answer += 1

        return answer

