class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n, m = len(source), len(pattern)
        removable = [False] * n
        for i in targetIndices:
            removable[i] = True

        neg = -10**9
        dp = [neg] * (m + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            # Keep this character without matching it, or remove it if allowed.
            ndp = dp[:]
            if removable[i]:
                for j, value in enumerate(dp):
                    if value != neg and value + 1 > ndp[j]:
                        ndp[j] = value + 1

            # Keep this character and use it to match the next pattern character.
            for j in range(m):
                if ch == pattern[j] and dp[j] > ndp[j + 1]:
                    ndp[j + 1] = dp[j]
            dp = ndp

        return dp[m]

