    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        rev = [[] for _ in range(n)]
        for a, b, w in edges:
            rev[b].append((a, w))

        inf = 10**18
        dist = [inf] * n
        dist[0] = 0
        pq = [(0, 0)]
        while pq:
            cost, v = heapq.heappop(pq)
            if cost != dist[v]:
                continue
            for u, w in rev[v]:
                nc = max(cost, w)
                if nc < dist[u]:
                    dist[u] = nc
                    heapq.heappush(pq, (nc, u))
        ans = max(dist)
        return -1 if ans == inf else ans

