from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        states = [(a, b) for a in range(3) for b in range(3) if a != b]
        predecessors = [[j for j, (x, y) in enumerate(states)
                        if x != a and y != b]
                       for a, b in states]

        dp = [cost[0][a] + cost[n - 1][b] for a, b in states]
        for k in range(1, n // 2):
            ndp = [0] * 6
            for i, (a, b) in enumerate(states):
                pair_cost = cost[k][a] + cost[n - 1 - k][b]
                ndp[i] = pair_cost + min(dp[j] for j in predecessors[i])
            dp = ndp
        return min(dp)

