class Solution:
    def calculateScore(self, s: str) -> int:
        stacks = [[] for _ in range(26)]
        score = 0
        for i, ch in enumerate(s):
            c = 25 - (ord(ch) - ord('a'))
            if stacks[c]:
                j = stacks[c].pop()
                score += i - j
            else:
                stacks[ord(ch) - ord('a')].append(i)
        return score

